  if (m == 3) return sin(atan(p.y, p.x) * 2.0 + length(p) * 8.0 * u_mapScale - t);     // swirl
  if (m == 4) return sin(p.x * 6.0 * u_mapScale + t) * sin(p.y * 6.0 * u_mapScale);    // bubble
  if (m == 5) return sin(length(p) * 12.0 * u_mapScale - t);                            // ring
